import type { Metadata } from "next";
import { getPostDetails } from "@/services/blog";
import PostDetails from "@/components/blog/detail";
import { notFound } from "next/navigation";

export const dynamic = "force-static";

export async function generateMetadata({
  params,
}: {
  params: { slug: string };
}): Promise<Metadata> {
  const detail = await getPostDetails(params.slug);
  if (!detail || detail.length === 0) return {};

  return {
    title: detail.title + " - TravelShop Booking",
    alternates: {
      canonical: "https://travelshopbooking.com/blog/" + params.slug,
    },
  };
}

export default async function BlogDetailPage({
  params,
}: {
  params: { slug: string };
}) {
  const detail = await getPostDetails(params.slug);
  
  if (!detail || detail.length === 0) {
    return (
      <main>
        <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-my-12 tw-font-display">
          <div className="tw-flex tw-justify-center">
            <div className="tw-max-w-[560px] tw-text-center tw-py-12">
              <div className="tw-text-[80px] tw-font-extrabold tw-leading-none tw-text-[#854ec9]/30">
                404
              </div>
              <h2 className="tw-text-[24px] tw-font-bold tw-text-[#14101c] tw-mt-2 tw-mb-3">
                Blog Post Not Found
              </h2>
              <p className="tw-text-[#5d556c] tw-mb-6">
                Sorry, the blog post you&apos;re looking for doesn&apos;t exist
                or may have been moved.
              </p>
              <a
                href="/blog"
                className="tw-inline-flex tw-items-center tw-gap-1 tw-rounded-full tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-px-5 tw-py-3 tw-no-underline tw-transition-colors"
              >
                ← Back to Blog
              </a>
            </div>
          </div>
        </div>
      </main>
    );
  }
  
  return <PostDetails slug={params.slug} post={detail} />;
}
